 680	 \subsection{Combining the $X$ and $Z$ measurements}
 681	\label{sec:combining}
 682	
 683	In this section our goal is to create a set of combined measurements
 684	that simultaneously measure the approximately-commuting measurements
 685	constructed in the previous section. We do this first for the points.
 686	Recall that $\mH_\alice$ and $\mH_\bob$ denote the Hilbert spaces corresponding to
 687	registers $\alice$ and $\bob$, respectively.
 688	
 689	\begin{lemma}\label{lem:qld-4-10}
 690	There exists a function $\delta_Q(\eps) = \poly(\eps)$ such that the following holds. 
 691		For every $x,z \in \F_q^m$ and $\mH \in \{ \mH_\alice, \mH_\bob\}$ there are projective measurements $\{ \hat{Q}^{x,z}_{a,b} \}_{a,b \in \F_q}$ acting on $\mathcal{H} \otimes (\C^q)^{\otimes \nqubits}$ such that:
 692		\begin{enumerate}
 693			\item (\textbf{Self-consistency}) On average over uniformly random $x,z \in \F_q^m$,
 694			\begin{equation}
 695				\label{eq:qld-q-self-cons}
 696				(\hat{Q}^{x,z}_{a,b})_{\alice \alice'}  \approx_{\delta_Q} (\hat{Q}^{x,z}_{a,b})_{\bob \alice''}\,.
 697			\end{equation}
 698			
 699			\item (\textbf{Consistency with $\hat{M}$}) On average over uniformly random $x,z \in \F_q^m$,
 700			\begin{gather}
 701				\label{eq:qld-q-cons-m-hat-xz}
 702					(\hat{Q}^{x,z}_{a,b})_{\alice \alice'} \approx_{\delta_Q} (\hat{M}^{(\Point,X),x}_{a} \hat{M}^{(\Point,Z),z}_b)_{\bob \alice''}\;, \\
 703								\label{eq:qld-q-cons-m-hat-zx}
 704					(\hat{Q}^{x,z}_{a,b})_{\alice \alice'} \approx_{\delta_Q} (\hat{M}^{(\Point,Z),z}_b  \hat{M}^{(\Point,X),x}_{a} )_{\bob \alice''}\;.
 705			\end{gather}
 706	              \end{enumerate}
 707	                    Furthermore, all symmetric equivalents of these approximations
 708	      also hold.
 709	\end{lemma}
 710	
 711	The construction of the measurements $\{ \hat{Q}^{x,z}_{a,b} \}$ whose existence is guaranteed in the lemma proceeds in three steps. In the first step, for every $(r,s)\in\F_q^2$ we combine the binary-outcome measurements $\hat{M}^{(\Point,X),x,r}_a$ and $\hat{M}^{(\Point,X),z,s}_b$; this is made possible by their approximate commutation as shown in Lemma~\ref{lem:qld-comm-cons}. In a second step, we show that the measurements thus constructed have a particular ``approximate linearity'' property, when seen as a function of the pair $(r,s)$. This allows us, in the third step, to combine them into a single measurement $\{ \hat{Q}^{x,z}_{a,b} \}$ with outcomes in $\F_q^2\cong \F_2^{2t}$ by applying the following  result from~\cite{NV17}:
 712		
 713		\begin{theorem}[Quantum linearity test]
 714		\label{thm:linearity}
 715			Let $0 \leq \delta \leq 1$, let $t$ be a positive integer, and let $\ket{\psi}$ be a state in a Hilbert space $\mathcal{H}_\alice \otimes \mathcal{H}_\bob$. Let $\{\mathcal{O}^u \}$ be a set of observables indexed by $u \in \F_2^t$ that act on $\mathcal{H}_\alice$. Suppose that on average over $u, u'$ chosen uniformly from $\F_2^t$, we have the following ``approximate linearity'' holds:
 716			\[
 717	(\mathcal{O}^u \mathcal{O}^{u'})_{\alice} \approx_\delta (\mathcal{O}^{u+u'})_{\alice}
 718			\]
 719			where the $\approx$ statement is taken with respect to the state $\ket{\psi}$. 
 720	Then there exists an extended state $\ket{\psi'}_{\alice \alice' \bob} = \ket{\psi}_{\alice \bob} \otimes \ket{0}_{\alice'}$ in an extended space $\mathcal{H}_{\alice} \otimes \mathcal{H}_\bob \otimes \mathcal{H}_{\alice'}$ and observables $\{ \mathcal{L}^u \}$ acting on $\mathcal{H}_\alice \otimes \mathcal{H}_{\alice'}$ such that for all $u, u' \in \F_2^t$, 
 721			\[
 722				\mathcal{L}^u \mathcal{L}^{u'} = \mathcal{L}^{u + u'} \qquad \text{and} \qquad (\mathcal{L}^u)_{\alice \alice'} \approx_\delta (\mathcal{O}^u)_\alice \,.
 723			\]
 724			Furthermore, the observable $\mathcal{L}^u = \Id$ when $u = 0$.
 725		\end{theorem}
 726			
 727			We now give the proof of Lemma~\ref{lem:qld-4-10}.
 728			
 729	\begin{proof}[Proof of Lemma~\ref{lem:qld-4-10}]
 730	For convenience in the proof we slightly abuse the notation $\approx_\delta$ to mean $\approx_{\poly(\eps)}$ for some polynomial function $\delta=\poly(\eps)$ that may differ each time the notation is used. 
 731	
 732	\textbf{First step: construction of projective binary measurements $\{ \hat{R}^\omega_{a,b} \}$.}
 733		For every $\omega = (x,z,r,s)$ and $a,b \in \F_2$, define a measurement operator
 734		\[
 735			\hat{R}^\omega_{a,b} = \hat{M}^{(\Point,\zpt),z,s}_{b} \cdot \hat{M}^{(\Point,\xpt),x,r}_{a} \cdot \hat{M}^{(\Point,\zpt),z,s}_{b} \,.
 736		\]
 737		It is clear that $\{ \hat{R}^\omega_{a,b} \}_{a,b\in\F_2}$ is a POVM. Observe that on average over uniformly random $\omega$, 
 738		\begin{align}
 739		\label{eq:qld-r-2}
 740		\hat{R}^\omega_{a,b} \approx_{\sqrt{\delta_{\acom}}} \hat{M}^{(\Point,\zpt),z,s}_{b} \cdot \hat{M}^{(\Point,\xpt),x,r}_{a}\;,
 741		\end{align}
 742		which follows from the approximate commutation relation of Lemma~\ref{lem:qld-comm-cons} and the projectivity of $\{ \hat{M}^{(\Point,\zpt),z,s}_{b} \}$, together with Fact~\ref{fact:add-a-proj}. Next we show that $\{ \hat{R}^\omega_{a,b} \}$ is approximately self-consistent:  we aim to show that on average over $\omega$, it holds that $(\hat{R}^\omega_{a,b})_{\alice \alice'} \simeq_\delta (\hat{R}^\omega_{a,b})_{\bob \alice''}$ for some polynomial function $\delta = \poly(\eps)$. To show this, we perform the following calculation: (recall the state $\ket{\hat{\psi}}$ defined in~\eqref{eq:def-psihat})
 743		\begin{align}
 744			&\E_\omega \sum_{a,b} \bra{\hat{\psi}} (\hat{R}^\omega_{a,b})_{\alice \alice'} \otimes (\hat{R}^\omega_{a,b})_{\bob \alice''} \ket{\hat{\psi}} \notag \\
 745			&\approx_{\delta_{\acom}^{1/4}} \E_\omega \sum_{a,b} \bra{\hat{\psi}} (\hat{M}^{(\Point,\zpt),z,s}_{b} \cdot \hat{M}^{(\Point,\xpt),x,r}_{a})_{\alice \alice'} \otimes (\hat{R}^\omega_{a,b})_{\bob \alice''} \ket{\hat{\psi}} \label{eq:qld-rw-self-cons-1} \\
 746			&\approx_{\delta_{\acom}^{1/4}} \E_\omega \sum_{a,b} \bra{\hat{\psi}} (\hat{M}^{(\Point,\zpt),z,s}_{b} \cdot \hat{M}^{(\Point,\xpt),x,r}_{a})_{\alice \alice'} \otimes (\hat{M}^{(\Point,\zpt),z,s}_{b} \cdot \hat{M}^{(\Point,\xpt),x,r}_{a})_{\bob \alice''} \ket{\hat{\psi}} \label{eq:qld-rw-self-cons-2} \\		
 747			&\approx_{\sqrt{\eps}} \E_\omega \sum_{a,b} \bra{\hat{\psi}} (\hat{M}^{(\Point,\zpt),z,s}_{b})_{\alice \alice'} \otimes (\hat{M}^{(\Point,\zpt),z,s}_{b} \cdot \hat{M}^{(\Point,\xpt),x,r}_{a})_{\bob \alice''} \ket{\hat{\psi}} \label{eq:qld-rw-self-cons-3} \\
 748			&= \E_\omega \sum_{b} \bra{\hat{\psi}} (\hat{M}^{(\Point,\zpt),z,s}_{b})_{\alice \alice'} \otimes (\hat{M}^{(\Point,\zpt),z,s}_{b})_{\bob \alice''} \ket{\hat{\psi}} \notag \\
 749			&\approx_{\eps} \E_\omega \sum_{b} \bra{\hat{\psi}} (\hat{M}^{(\Point,\zpt),z,s}_{b})_{\alice \alice'} \ket{\hat{\psi}} \label{eq:qld-rw-self-cons-4} \\
 750			&= 1\;. \notag
 751		\end{align}
 752	   	The approximation in~\eqref{eq:qld-rw-self-cons-1} is derived by bounding the magnitude of the difference:
 753		\begin{align*}
 754			&\left | \E_\omega \sum_{a,b} \bra{\hat{\psi}} (\hat{R}^\omega_{a,b} - \hat{M}^{(\Point,\zpt),z,s}_{b} \cdot \hat{M}^{(\Point,\xpt),x,r}_{a})_{\alice \alice'} \otimes (\hat{R}^\omega_{a,b})_{\bob \alice''} \ket{\hat{\psi}} \right | \\
 755			&\leq \sqrt{\E_\omega \sum_{a,b} \bra{\hat{\psi}} (\hat{R}^\omega_{a,b} - \hat{M}^{(\Point,\zpt),z,s}_{b} \cdot \hat{M}^{(\Point,\xpt),x,r}_{a})_{\alice \alice'}^2 \ket{\hat{\psi}} } \cdot \sqrt{\E_\omega \sum_{a,b} \bra{\psi} (\hat{R}^\omega_{a,b})^2_{\bob \alice''} \ket{\psi} } \\
 756			&\leq \sqrt{\delta_{\acom}^{1/2}} \cdot \sqrt{1}\;,
 757		\end{align*}
 758		where the second line follows from Cauchy-Schwarz, and the third line follows from~\eqref{eq:qld-r-2} and the fact that $\sum_{a,b} (\hat{R}^\omega_{a,b})^2 \leq \Id$. The approximation in~\eqref{eq:qld-rw-self-cons-2} follows from a similar calculation. 
 759		The approximation in~\eqref{eq:qld-rw-self-cons-3} is derived by bounding the magnitude of the difference:
 760		\begin{align}
 761			&\left | \E_\omega \sum_{a,b} \bra{\hat{\psi}} (\hat{M}^{(\Point,\zpt),z,s}_{b} \cdot (\Id - \hat{M}^{(\Point,\xpt),x,r}_{a}))_{\alice \alice'}  \otimes (\hat{M}^{(\Point,\zpt),z,s}_{b} \cdot \hat{M}^{(\Point,\xpt),x,r}_{a})_{\bob \alice''} \ket{\hat{\psi}} \right | \notag \\
 762			&= \left | \E_\omega  \bra{\hat{\psi}} \Big(\sum_b \hat{M}^{(\Point,\zpt),z,s}_{b} \otimes \hat{M}^{(\Point,\zpt),z,s}_{b}\Big) \cdot \Big(\sum_{a} (\Id - \hat{M}^{(\Point,\xpt),x,r}_{a}) \otimes \hat{M}^{(\Point,\xpt),x,r}_{a} \Big) \ket{\hat{\psi}} \right | \\
 763			&\leq \sqrt{\E_\omega \sum_{a} \bra{\hat{\psi}} (\Id - \hat{M}^{(\Point,\xpt),x,r}_{a})_{\alice \alice'}^2 \otimes (\hat{M}^{(\Point,\xpt),x,r}_{a})_{\bob \alice''}^2 \ket{\hat{\psi}}} \label{eq:qld-rw-self-cons-3-1}\\
 764	                &= \sqrt{\E_\omega \sum_{a} \bra{\hat{\psi}} (\Id - \hat{M}^{(\Point,\xpt),x,r}_{a})_{\alice \alice'} \otimes (\hat{M}^{(\Point,\xpt),x,r}_{a})_{\bob \alice''} \ket{\hat{\psi}}} \label{eq:qld-rw-self-cons-3-2}\\
 765	                &= \sqrt{ 1 - \E_{\omega} \sum_a \bra{\hat{\psi}} (\hat{M}^{(\Point,\xpt),x,r}_{a})_{\alice \alice'} \ot  (\hat{M}^{(\Point,\xpt),x,r}_{a})_{\bob \alice''} \ket{\hat{\psi}}} \label{eq:qld-rw-self-cons-3-3}\\
 766	                &=\sqrt{ \frac{1}{2} \E_{\omega} \sum_a \bra{\hat{\psi}} ( (\hat{M}^{(\Point,\xpt),x,r}_{a})_{\alice \alice'} \ot I_{\bob \alice''} - I_{\alice \alice'} \ot  (\hat{M}^{(\Point,\xpt),x,r}_{a})_{\bob \alice''})^2 \ket{\hat{\psi}}} \label{eq:qld-rw-self-cons-3-4}\\
 767			&\leq \sqrt{\eps}\;. \label{eq:qld-rw-self-cons-3-5}
 768		\end{align}
 769		Here \Cref{eq:qld-rw-self-cons-3-1} follows from the Cauchy-Schwarz inequality, the projectivity of $\hat{M}^{(\Point,\xpt),x,r}_{a}$, and the fact that $\sum_b \hat{M}^{(\Point,\zpt),z,s}_{b} \otimes \hat{M}^{(\Point,\zpt),z,s}_{b} \leq \Id$. \Cref{eq:qld-rw-self-cons-3-2,eq:qld-rw-self-cons-3-3,eq:qld-rw-self-cons-3-4} follow from projectivity and completeness of $\hat{M}^{(\Point, \xpt), x, r}_{a}$. \Cref{eq:qld-rw-self-cons-3-5} follows from the self-consistency of $\hat{M}^{(\Point,\xpt),x,r}_{a}$, established in \Cref{lem:qld-comm-cons}. 
 770	
 771	        The approximation in~\eqref{eq:qld-rw-self-cons-4} follows from the self-consistency of $\hat{M}^{(\Point, \xpt), x, r}_a$, again from \Cref{lem:qld-comm-cons}, together with projectivity and \Cref{fact:agreement}.
 772	
 773	        
 774		
 775		This shows that $(\hat{R}^\omega_{a,b})_{\alice \alice'} \simeq_\delta (\hat{R}^\omega_{a,b})_{\bob \alice''}$, as desired. Combined with \Cref{fact:agreement}, we have
 776		\begin{equation}
 777			\label{eq:rw-sc}
 778			(\hat{R}^\omega_{a,b})_{\alice \alice'} \approx_\delta (\hat{R}^\omega_{a,b})_{\bob \alice''}\;.
 779		\end{equation}
 780	
 781	
 782			Finally we apply the orthonormalization Lemma (Lemma~\ref{lem:ortho}) to $\{ \hat{R}^\omega_{a,b} \}$ in order to obtain projective measurements $\{ \hat{L}^\omega_{a,b} \}$ such that on average over $\omega$,
 783		\begin{equation}\label{eq:rl-close}
 784			\hat{L}^\omega_{a,b} \approx_{\delta} \hat{R}^\omega_{a,b}\;.
 785		\end{equation}
 786		
 787		\textbf{Second step: approximate linearity relations for $\{ \hat{R}^\omega_{a,b} \}$.}
 788		We proceed in three steps. First we establish linearity relations for $\{ \hat{M}^{(\Point,W),u,r}_b \}$. For all $W \in \{X,Z\}$, $u \in \F_q^m$, $r, r' \in \F_q$ and $c \in \F_2$, 
 789		\begin{align}
 790			\sum_{\substack{b,b' \in \F_2 : \\ b + b' = c }} \hat{M}^{(\Point,W),u,r}_b \, \hat{M}^{(\Point,W),u,r'}_{b'} &= \sum_{\substack{a,a' \in \F_q: \\ \tr(ar + a'r') = c}} \hat{M}^{(\Point,W),u}_a \cdot \hat{M}^{(\Point,W),u}_{a'} \notag\\
 791			&= \sum_{a : \tr(a (r +r')) = c } \hat{M}^{(\Point,W),u}_a \notag\\
 792			&= \hat{M}^{(\Point,W),u,r+r'}_c\;,\label{eq:m-lin}
 793		\end{align}
 794		where the second line follows from projectivity of $\{\hat{M}^{(\Point,W),u}_a\}$. 
 795		
 796		Second we show approximate linearity of the $\{ \hat{R}^\omega_{a,b} \}$. On average over $x,z \in \F_q^m$ and $r,r',s,s' \in \F_q$, 
 797		\begin{align}
 798		& \sum_{\substack{a,b,a',b' : \\ a + a' = c \\ b + b' = d}} \Big (\hat{R}^{x,z,r,s}_{a,b} \cdot \hat{R}^{x,z,r',s'}_{a',b'} \Big)_{\alice \alice'} \notag\\
 799		&\approx_\delta \sum_{\substack{a,b,a',b' : \\ a + a' = c \\ b + b' = d}} \Big( \hat{R}^{x,z,r,s}_{a,b} \Big)_{\alice \alice'} \otimes \Big( \hat{R}^{x,z,r',s'}_{a',b'} \Big)_{\bob \alice''} \label{eq:qld-r-52} \\
 800			&\approx_\delta \sum_{\substack{a,b,a',b': \\ a + a' = c \\ b + b' = d}} \Big( \hat{M}^{(\Point,\zpt),z,s}_{b} \cdot \hat{M}^{(\Point,\xpt),x,r}_{a}
 801	 \Big)_{\alice \alice'} \otimes \Big(\hat{M}^{(\Point,\zpt),z,s'}_{b'} \cdot \hat{M}^{(\Point,\xpt),x,r'}_{a'} \Big)_{\bob \alice''} \label{eq:qld-r-53} \\
 802	 	&\approx_\delta \sum_{\substack{b,b': \\ b + b' = d}} \Big( \hat{M}^{(\Point,\zpt),z,s}_{b}
 803	 \Big)_{\alice \alice'} \otimes \Big(\hat{M}^{(\Point,\zpt),z,s'}_{b'} \cdot \hat{M}^{(\Point,\xpt),x,r+r'}_{c} \Big)_{\bob \alice''} \label{eq:qld-r-54} \\
 804	 &\approx_\delta \sum_{\substack{b,b' : \\ b + b' = d}} \Big( \hat{M}^{(\Point,\zpt),z,s}_{b}
 805	 \Big)_{\alice \alice'} \otimes \Big(\hat{M}^{(\Point,\xpt),x,r+r'}_{c} \cdot \hat{M}^{(\Point,\zpt),z,s'}_{b'}  \Big)_{\bob \alice''} \;.\label{eq:qld-r-55}
 806	 \end{align}
 807		In each approximation, the answer summation is over $c,d \in \F_2$. Each approximation follows by applying a previously derived approximation to part of the expression, together with \Cref{fact:add-a-proj}.\anote{Eventual TODO: split up all these steps} Specifically, line~\eqref{eq:qld-r-52} uses the self-consistency of $\{ \hat{R}^\omega_{a,b} \}$ shown in~\eqref{eq:rw-sc}. Line~\eqref{eq:qld-r-53} follows from using~\eqref{eq:qld-r-2} twice. Line~\eqref{eq:qld-r-54} follows from the self-consistency and linearity properties of $\{ \hat{M}^{(\Point,X),x,r}_a \}$ shown in Lemma~\ref{lem:qld-comm-cons} and~\eqref{eq:m-lin} respectively. Line~\eqref{eq:qld-r-55} follows from the approximate commutativity relation shown in Lemma~\ref{lem:qld-comm-cons}.  Continuing,
 808	 \begin{align}
 809	\text{\eqref{eq:qld-r-55}} &\approx_\delta \Big(\hat{M}^{(\Point,\xpt),x,r+r'}_{c} \cdot \hat{M}^{(\Point,\zpt),z,s+s'}_{d}  \Big)_{\bob \alice''} \label{eq:qld-r-56} \\
 810	 &\approx_\delta \Big ( \hat{R}^{x,z,r+r',s+s'}_{c,d} \Big)_{\bob \alice''} \label{eq:qld-r-57} \\
 811	 &\approx_\delta \Big ( \hat{R}^{x,z,r+r',s+s'}_{c,d} \Big)_{\alice \alice'} \label{eq:qld-r-58}.
 812		\end{align}	
 813	Line~\eqref{eq:qld-r-56} follows from self-consistency and linearity properties of $\{ \hat{M}^{(\Point,Z),z,s}_b \}$. Line~\eqref{eq:qld-r-57} follows from~\eqref{eq:qld-r-2} and \Cref{lem:qld-comm-cons}, and line~\eqref{eq:qld-r-58} follows from the self-consistency of $\{ \hat{R}^\omega_{a,b} \}$ from Eq.~\eqref{eq:rw-sc}. 
 814		
 815	Third we deduce approximate linearity of the $\{ \hat{L}^\omega_{a,b} \}$. On average over $x,z \in \F_q^m$, and $r,r',s,s' \in \F_q$, we have
 816		\begin{align}
 817		\sum_{\substack{a,b,a',b': \\ a + a' = c \\ b + b' = d}}  \Big ( \hat{L}^{x,z,r,s}_{a,b} \, \hat{L}^{x,z,r',s'}_{a',b'} \Big)_{\alice \alice'} &\approx_\delta  \sum_{\substack{a,b,a',b': \\ a + a' = c \\ b + b' = d}} \Big( \hat{L}^{x,z,r,s}_{a,b} \Big)_{\alice \alice'} \otimes \Big (\hat{L}^{x,z,r',s'}_{a',b'} \Big)_{\bob \alice''}\notag \\
 818			&\approx_\delta  \sum_{\substack{a,b,a',b' : \\ a + a' = c \\ b + b' = d}}  \Big( \hat{R}^{x,z,r,s}_{a,b} \Big)_{\alice \alice'} \otimes \Big( \hat{R}^{x,z,r',s'}_{a',b'} \Big)_{\bob \alice''} \notag\\
 819			&\approx_\delta \Big ( \hat{R}^{x,z,r+r',s+s'}_{c,d} \Big)_{\alice \alice'} \notag\\
 820			&\approx_\delta \Big ( \hat{L}^{x,z,r+r',s+s'}_{c,d} \Big)_{\alice \alice'}\;.\label{eq:l-al}
 821		\end{align}
 822		The first two approximations follow from the closeness of the $\{ \hat{R}^\omega_{a,b} \}$ and $\{ \hat{L}^\omega_{a,b} \}$  guaranteed by~\eqref{eq:rl-close} as well as the self-consistency of $\{ \hat{R}^\omega_{a,b} \}$ shown in~\eqref{eq:rw-sc}. The third approximation follows from the linearity properties of $\{ \hat{R}^\omega_{a,b} \}$ in~\eqref{eq:qld-r-55}. 
 823		
 824		\textbf{Third step: construction of $\{ \hat{Q}^{x,z}_{a,b} \}$.}
 825		For each $\omega$ define an observable $\mathcal{O}^\omega = \sum_{a,b \in \F_2} (-1)^{a+ b} \hat{L}^\omega_{a,b}$.  The self-consistency of $\mathcal{O}^\omega$ between registers $\alice \alice'$ and $\bob \alice''$ follows from the self-consistency of the $\{ \hat{L}^\omega_{a,b} \}$, which is obtained by combining~\eqref{eq:rw-sc} and~\eqref{eq:rl-close}. We now verify approximate linearity. On average over $x,z \in \F_q^m$, and $r,r',s,s' \in \F_q$, 
 826		\begin{align*}
 827			\mathcal{O}^{x,z,r,s} \, \mathcal{O}^{x,z,r',s'} &= \sum_{a,b,a',b'} (-1)^{a + b + a' + b'} \hat{L}^{x,z,r,s}_{a,b} \, \hat{L}^{x,z,r',s'}_{a',b'} \\
 828			&\approx_\delta \sum_{c,c'} (-1)^{c+c'} \hat{L}^{x,z,r+r',s+s'}_{c,c'} \\
 829			&= \mathcal{O}^{x,z,r+r',s+s'}\,
 830		\end{align*}
 831		where the approximation follows from the approximate linearity properties of $\{ \hat{L}^\omega_{a,b} \}$ shown in~\eqref{eq:l-al}.
 832		Identify the field $\F_q$ with the vector space $\F_2^t$, and thus we treat pairs $(r,s)$ as vectors in $\F_2^{2t}$. For every $x,z \in \F_q^m$, we can apply Theorem~\ref{thm:linearity} to the collection of observables $\{ \mathcal{O}^{x,z,r,s} \}_{r,s \in \F_q}$ to obtain the existence of ``{exactly linear}'' observables $\{ \mathcal{L}^{x,z,r,s} \}$ that are $\delta$-close to $\{ \mathcal{O}^{x,z,r,s} \}$, on average over the choice of $x,z,r,s$. By assuming that $\ket{\hat{\psi}}$ has sufficiently many ancilla zero qubits, we do not need to extend the state further. 
 833		
 834		We are ready to define the measurements $\{\hat{Q}^{x,z}_{a,b} \}$ whose existence is claimed in the statement of the lemma. For all $x,z\in \F_q^m$ and $a,b \in \F_q$, define
 835		\[
 836			\hat{Q}^{x,z}_{a,b} = \E_{r,s} (-1)^{\tr(ra + sb)} \mathcal{L}^{x,z,r,s}\;.
 837		\]
 838		This operator is a projection (and thus positive semidefinite):
 839		\begin{align*}
 840		(\hat{Q}^{x,z}_{a,b})^2 &= \E_{r,s,r',s'} (-1)^{\tr((r+r')a + (s+s')b)} \mathcal{L}^{x,z,r,s} \, \mathcal{L}^{x,z,r',s'}\\ 
 841		&= \E_{r,s,r',s'} (-1)^{\tr((r+r')a + (s+s')b)} \mathcal{L}^{x,z,r+r',s+s'} \\
 842		&= \E_{r,s} (-1)^{\tr(ra + sb)}  \mathcal{L}^{x,z,r,s}\;.
 843		\end{align*}
 844		The second equality follows from the exact linearity of the $\{ \mathcal{L}^{x,z,r,s} \}$. Next, the operators sum to identity:
 845		\begin{align*}
 846			\sum_{a,b} \hat{Q}^{x,z}_{a,b} &= \E_{r,s} \sum_{a,b} (-1)^{\tr(ra + sb)} \mathcal{L}^{x,z,r,s} \\
 847			&= \mathcal{L}^{x,z,0,0} \\
 848			&= \Id\;.
 849		\end{align*}
 850		Thus $\{\hat{Q}^{x,z}_{a,b}\}$ forms a projective measurement.
 851		
 852		We establish self-consistency:
 853		\begin{align*}
 854			\Big( \hat{Q}^{x,z}_{a,b} \Big)_{\alice \alice'} &= \Big( \E_{r,s} (-1)^{\tr(ra + sb)} \mathcal{L}^{x,z,r,s} \Big)_{\alice \alice'} \\
 855			&\approx_\delta \Big( \E_{r,s} (-1)^{\tr(ra + sb)} \mathcal{O}^{x,z,r,s} \Big)_{\alice \alice'} \\
 856			&\approx_\delta \Big( \E_{r,s} (-1)^{\tr(ra + sb)} \mathcal{O}^{x,z,r,s} \Big)_{\bob \alice''} \\
 857			&\approx_\delta \Big( \hat{Q}^{x,z}_{a,b} \Big)_{\bob \alice''}\,.
 858		\end{align*}
